-- 038_fix_alphabet_meaning_questions.sql
-- migration 037 mistakenly phrased l0's 'meaning' questions as
-- listening exercises ("Quelle lettre entendez-vous ?"), but the
-- 'meaning' question type has no audio button anywhere in LessonPage.jsx
-- (only 'tile'/'audio'/'image_vocab' do) — it's pure text: the word is
-- shown as a written prompt, no listening involved. Reverts to reading-
-- based phrasing (as in migration 036) and, since there's no audio
-- constraint on a text-only question, expands to all 33 letters instead
-- of stopping at 32. 'tile' questions (which DO have a play button) keep
-- migration 037's letter-audio approach unchanged.

delete from public.lesson_questions where lesson_id = 'l0' and question_type = 'meaning';

